create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,role text not null check(role in('user','assistant')),content text not null,feedback text check(feedback in('up','down')),created_at timestamptz not null default now());create index if not exists idx_msg_c on public.messages(conversation_id);create index if not exists idx_msg_d on public.messages(created_at desc);
